import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
// Retail API migration checks driven by core/api-rules.json (generated by tools/build-api-rules.mjs from Blizzard's UI source).
// Static and lexical only: a finding is evidence to review, not proof of runtime behaviour.
export const rules=JSON.parse(fs.readFileSync(fileURLToPath(new URL('./api-rules.json',import.meta.url)),'utf8'));
const CALLS=new Set(['CallExpression','StringCallExpression','TableCallExpression']);
const REGISTER=new Set(['RegisterEvent','RegisterUnitEvent','RegisterEventCallback','RegisterCallback','RegisterMessage']);
const SECRET_OPS=new Set(['==','~=','<','>','<=','>=','+','-','*','/','%','^','..']);
const SECRET_AWARE=/\b(issecretvalue|issecrettable|canaccesssecrets|hasanysecretvalues|scrubsecretvalues|C_Secrets)\b/;
const LOCKDOWN_AWARE=/\b(InChatMessagingLockdown|AddOnMessageLockdown)\b/;
const GROUP_TITLE={removed:'Removed API',deprecated:'Deprecated API',combatlog:'Combat log API unavailable'};

// Dotted global name of an expression (GetSpellInfo, C_SpellBook.GetSpellInfo), or null for locals, fields of locals and computed keys.
export function dotted(n){if(n?.type==='Identifier')return n.isLocal?null:n.name;if(n?.type==='MemberExpression'&&n.indexer==='.'){const b=dotted(n.base);return b?b+'.'+n.identifier.name:null;}return null;}
function mentions(node,name){let found=false;(function walk(n){if(found||!n||typeof n!=='object')return;if(Array.isArray(n)){n.forEach(walk);return;}if(dotted(n)===name){found=true;return;}for(const [k,v] of Object.entries(n))if(k!=='loc'&&k!=='range')walk(v);})(node);return found;}
const children=n=>Object.entries(n).filter(([k,v])=>k!=='loc'&&k!=='range'&&!(n.type==='MemberExpression'&&k==='identifier')&&!(k==='key'&&n.type==='TableKeyString')&&v&&typeof v==='object');
const lastIsExit=body=>['ReturnStatement','BreakStatement'].includes(body?.at(-1)?.type);

// Globals the addon defines itself (polyfills) are never reported.
export function definedGlobals(ast){const set=new Set();(function walk(n){if(!n||typeof n!=='object')return;if(Array.isArray(n)){n.forEach(walk);return;}
  if(n.type==='FunctionDeclaration'&&n.identifier&&!n.isLocal){const d=dotted(n.identifier);if(d)set.add(d);}
  if(n.type==='AssignmentStatement')for(const v of n.variables){const d=dotted(v);if(d)set.add(d);}
  for(const [,v] of children(n))walk(v);})(ast);return set;}

// A reference is guarded when nil is handled before use: `X or Y`, `X and X()`, `if X then X() end`, `if not X then return end`.
function guarded(node,name,path,usage){
  let child=node;
  for(let i=path.length-1;i>=0;i--){const p=path[i];
    if(p.type==='LogicalExpression'){if(usage==='reference'&&path.slice(i+1).every(a=>a.type==='LogicalExpression'))return true;if(p.operator==='and'&&p.right===child&&mentions(p.left,name))return true;}
    if((p.type==='IfClause'||p.type==='ElseifClause'||p.type==='WhileStatement')&&p.condition){if(p.condition!==child&&mentions(p.condition,name))return true;if(p.condition===child&&usage==='reference')return true;}
    if(Array.isArray(p.body)){const at=p.body.indexOf(child);for(let j=0;j<at;j++){const s=p.body[j];if(s.type==='IfStatement'&&mentions(s.clauses[0].condition,name)&&lastIsExit(s.clauses[0].body))return true;}}
    child=p;
  }
  return false;
}
function usageOf(node,parent){
  if(CALLS.has(parent?.type)&&parent.base===node)return 'call';
  if(parent?.type==='CallExpression'&&parent.arguments[0]===node&&['pcall','xpcall'].includes(dotted(parent.base)))return 'pcall';
  return 'reference';
}

export function checkApi(ast,text,file,add,{projectGlobals=new Set()}={}){
  const seen=new Set(),secretLocals=new WeakMap();const lib=/(^|\/)libs?\//i.test(file)?' This is in an embedded library; prefer updating the library.':'';
  const secretAware=SECRET_AWARE.test(text),lockdownAware=LOCKDOWN_AWARE.test(text);
  const once=(key,fn)=>{if(seen.has(key))return;seen.add(key);fn();};
  function global(node,path){
    const name=dotted(node),rule=name&&rules.globals[name];if(!rule||projectGlobals.has(name))return;const parent=path.at(-1);
    if(parent?.type==='AssignmentStatement'&&parent.variables.includes(node))return;
    if(node.type==='Identifier'&&parent?.type==='MemberExpression'&&parent.base===node&&rules.globals[dotted(parent)])return;
    const usage=usageOf(node,parent),line=node.loc.start.line,use=rule.replacement?' Use '+rule.replacement+' instead.':'';const note=rule.note?' '+rule.note:'';const src=' Source: '+rule.source+'.';
    once(name+':'+line,()=>{
      if(guarded(node,name,path,usage)){add('info','api','Guarded fallback: '+name,file,line,(rule.group==='deprecated'?name+' is a deprecated shim that only exists while the loadDeprecationFallbacks CVar is on. The code handles nil, so it is safe, but prefer the current API first.':name+' does not exist on Retail ('+(rule.removedIn?'removed in '+rule.removedIn:'unavailable')+'). The code handles nil, so this branch is dead on Retail and can stay for other clients.')+use+lib+src,{confidence:'Guard detected statically',rule:rule.group});return;}
      let severity=rule.severity,detail;
      if(rule.group==='removed')detail=name+' was removed from Retail in '+rule.removedIn+'. '+(usage==='reference'?'Referencing it yields nil, so a later call fails with “attempt to call a nil value”.':usage==='pcall'?'pcall hides the error, so this always fails silently on Retail.':'Calling it raises “attempt to call a nil value”.');
      else if(rule.group==='deprecated')detail=name+' only exists while the loadDeprecationFallbacks CVar is on, and Blizzard will remove it in a later patch.';
      else detail='Since 12.0.0 combat log data is not available to addons. '+name+' is not callable from addon code.';
      if(usage==='pcall'&&severity==='error')severity='warning';
      add(severity,'api',GROUP_TITLE[rule.group]+': '+name,file,line,detail+use+note+lib+src,{confidence:rule.group==='deprecated'?'Confirmed shim in Blizzard UI source':'Confirmed against Blizzard UI source',rule:rule.group,replacement:rule.replacement||undefined});
    });
  }
  function event(node,path){
    const value=node.value??node.raw?.slice(1,-1),rule=rules.events[value];if(!rule)return;const parent=path.at(-1),line=node.loc.start.line;
    const registered=CALLS.has(parent?.type)&&parent.base?.type==='MemberExpression'&&REGISTER.has(parent.base.identifier.name)||parent?.type==='TableValue';
    const combat=rule.group==='combatlog',why=combat?value+' can no longer be registered since 12.0.0; registering it raises an error and addons no longer receive combat log events.':value+' no longer exists on Retail (removed in '+rule.removedIn+').'+(rule.replacement?' Use '+rule.replacement+'.':'');
    once('event:'+value+':'+line,()=>add(registered?rule.severity:'info','api',(registered?'Removed event: ':'Handler for removed event: ')+value,file,line,why+(registered?'':' This line only compares or stores the name; it is dead code on Retail.')+lib+' Source: '+(rule.source||'Blizzard API documentation')+'.',{confidence:registered?'Confirmed against Blizzard UI source':'Lexical match',rule:'event'}));
  }
  function method(node,path){
    const m=node.base.identifier.name,rule=rules.methods[m];if(!rule)return;const line=node.loc.start.line;
    if(rule.group==='lockdown'){if(lockdownAware)return;once('lockdown:'+m,()=>add('info','api','Addon messages blocked in lockdown: '+m,file,line,lockdownText(m+' ('+rule.owner+')')+lib,{confidence:'Advisory',rule:'lockdown'}));return;}
    once(m+':'+line,()=>add(rule.severity,'api','Removed method: '+m,file,line,rule.owner+':'+m+' was removed in '+rule.removedIn+'. The receiver type cannot be proved statically, so check that this is a '+rule.owner+'.'+lib+' Source: '+rule.source+'.',{confidence:'Method name match',rule:'method'}));
  }
  const lockdownText=what=>'In Midnight, '+what+' is blocked while a Mythic+ run, PvP match or boss encounter is in progress, and the send returns Enum.SendAddonMessageResult.AddOnMessageLockdown. Check C_ChatInfo.InChatMessagingLockdown() before sending and queue the message until it clears.';
  function call(node,path){
    const name=dotted(node.base);
    if(name&&rules.lockdown[name]&&!lockdownAware)once('lockdown:'+name,()=>add('info','api','Messaging blocked in lockdown: '+name,file,node.loc.start.line,lockdownText(name)+lib+' Source: '+rules.lockdown[name].source+'.',{confidence:'Advisory',rule:'lockdown'}));
    const flags=name&&rules.secret[name];if(!flags)return;
    const parent=path.at(-1),operand=parent?.type==='MemberExpression'&&parent.base===node?parent:node,host=operand===node?parent:path.at(-2);
    if(host?.type==='BinaryExpression'&&SECRET_OPS.has(host.operator)&&!comparesNil(host)||host?.type==='UnaryExpression'&&host.operator==='-')secret(name,flags,node.loc.start.line);
    const stmt=path.findLast(p=>p.type==='LocalStatement'||p.type==='AssignmentStatement');
    if(stmt&&(stmt.init?.[0]===node||stmt.init?.[0]===operand)){const fn=scope(path);if(!secretLocals.has(fn))secretLocals.set(fn,new Map());for(const v of stmt.variables.slice(0,1))if(v.type==='Identifier'&&v.isLocal)secretLocals.get(fn).set(v.name,{name,flags,line:node.loc.start.line});}
  }
  function secret(name,flags,line){once('secret:'+name+':'+line,()=>add(secretAware?'info':'warning','api','Secret value in comparison or arithmetic: '+name,file,line,name+' can return a secret value in Midnight ('+flags.join(', ')+'), mainly in combat and instanced content. Comparing or doing arithmetic on a secret raises a Lua error. Test it with issecretvalue() first, or pass it straight to a widget that accepts secrets.'+(secretAware?' This file already uses secret-value checks; confirm this line is covered.':'')+lib+' Source: https://warcraft.wiki.gg/wiki/Secret_Values.',{confidence:'Heuristic: traced within this file only',rule:'secret'}));}
  // Locals are tracked per enclosing function (and the functions around it), so a name reused elsewhere is not confused.
  const scope=path=>path.findLast(p=>p.type==='FunctionDeclaration'||p.type==='Chunk');
  const comparesNil=n=>n.left?.type==='NilLiteral'||n.right?.type==='NilLiteral';
  function binary(node,path){if(comparesNil(node))return;for(const side of [node.left,node.right]){let root=side;while(root?.type==='MemberExpression'||root?.type==='IndexExpression')root=root.base;if(root?.type!=='Identifier'||!root.isLocal)continue;
    for(const fn of path.filter(p=>p.type==='FunctionDeclaration'||p.type==='Chunk').reverse()){const s=secretLocals.get(fn)?.get(root.name);if(s){if(node.loc.start.line>=s.line)secret(s.name,s.flags,node.loc.start.line);break;}}}}

  (function walk(n,path){
    if(!n||typeof n!=='object')return;if(Array.isArray(n)){n.forEach(c=>walk(c,path));return;}
    if(n.type==='Identifier'||n.type==='MemberExpression')global(n,path);
    else if(n.type==='StringLiteral')event(n,path);
    if(CALLS.has(n.type)){call(n,path);if(n.base?.type==='MemberExpression'&&n.base.indexer===':')method(n,path);}
    if(n.type==='BinaryExpression'&&SECRET_OPS.has(n.operator))binary(n,path);
    const next=[...path,n];for(const [,v] of children(n))walk(v,next);
  })(ast,[]);
}
